+      line-height: 1.6;
+    }
+
+    form {
+      display: grid;
+      gap: 1rem;
+    }
+
+    .form-field {
+      padding: 1rem;
+      border: 1px solid rgba(148, 163, 184, 0.35);
+      border-radius: 1rem;
+      background: rgba(248, 250, 252, 0.85);
+    }
+
+    .checkbox-row {
+      display: grid;
+      grid-template-columns: auto 1fr;
+      gap: 0.9rem;
+      align-items: start;
+    }
+
+    input[type="checkbox"] {
+      width: 1.2rem;
+      height: 1.2rem;
+      margin: 0.15rem 0 0;
+      accent-color: var(--accent);
+    }
+
+    label {
+      font-weight: 600;
+      line-height: 1.5;
+    }
+
+    .required {
+      color: var(--error);
+      margin-left: 0.2rem;
+    }
+
+    .helper-text,
+    .error-text,
+    .status {
+      margin: 0.7rem 0 0;
+      font-size: 0.95rem;
+      line-height: 1.5;
+    }
+
+    .helper-text {
+      color: var(--muted);
+    }
+
+    .error-text {
+      color: var(--error);
+      font-weight: 600;
+    }
+
+    .status {
+      min-height: 1.5rem;
+      color: #166534;
+      font-weight: 600;
+    }
+
+    button {
+      border: 0;
+      border-radius: 999px;
+      padding: 0.95rem 1.2rem;
+      font: inherit;
+      font-weight: 700;
+      color: #ffffff;
+      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
+      cursor: pointer;
+      box-shadow: 0 12px 30px rgba(37, 99, 235, 0.28);
+    }
+
+    a {
+      color: var(--accent-strong);
+    }
+
+    input[type="checkbox"]:focus-visible,
+    button:focus-visible,
+    a:focus-visible {
+      outline: 3px solid #0f172a;
+      outline-offset: 3px;
+    }
+
+    input[aria-invalid="true"] {
+      outline: 2px solid var(--error);
+      outline-offset: 3px;
+    }
+
+    [hidden] {
+      display: none !important;
+    }
+
+    @media (max-width: 480px) {
+      .card {
+        padding: 1.4rem;
+        border-radius: 1.25rem;
+      }
+    }
+
+    @media (prefers-reduced-motion: reduce) {
+      *,
+      *::before,
+      *::after {
+        transition-duration: 0.01ms !important;
+        animation-duration: 0.01ms !important;
+        animation-iteration-count: 1 !important;
+        scroll-behavior: auto !important;
+      }
+    }
+
+    @media (forced-colors: active) {
+      .card,
+      .form-field,
+      button {
+        border: 1px solid CanvasText;
+        box-shadow: none;
+      }
+
+      button {
+        background: ButtonFace;
+        color: ButtonText;
+      }
+    }
+  </style>
+</head>
+<body>
+  <a class="skip-link" href="#main-content">Skip to main content</a>
+
+  <main id="main-content" tabindex="-1">
+    <section class="card" aria-labelledby="page-title">
+      <p class="eyebrow">Account setup</p>
+      <h1 id="page-title">Confirm your consent</h1>
+      <p class="intro">Review the terms once, then confirm your agreement to continue creating your account.</p>
+
+      <form id="consent-form" novalidate>
+        <div class="form-field">
+          <div class="checkbox-row">
+            <input
+              id="consent"
+              name="consent"
+              type="checkbox"
+              required
+              aria-describedby="consent-help consent-error"
+            >
+            <label for="consent">
+              I agree to the <a href="#terms">Terms of Use</a><span class="required" aria-hidden="true">*</span>
+            </label>
+          </div>
+          <p id="consent-help" class="helper-text">Required to finish setup and activate your access.</p>
+          <p id="consent-error" class="error-text" hidden>Error: You must agree to the Terms of Use before continuing.</p>
+        </div>
+
+        <button type="submit">Continue</button>
+        <p id="form-status" class="status" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById("consent-form");
+    const checkbox = document.getElementById("consent");
+    const error = document.getElementById("consent-error");
+    const status = document.getElementById("form-status");
+
+    function clearError() {
+      checkbox.removeAttribute("aria-invalid");
+      error.hidden = true;
+    }
+
+    form.addEventListener("submit", (event) => {
+      status.textContent = "";
+
+      if (checkbox.checked) {
+        clearError();
+        status.textContent = "Consent saved. You're ready to continue.";
+        event.preventDefault();
+        return;
+      }
+
+      event.preventDefault();
+      checkbox.setAttribute("aria-invalid", "true");
+      error.hidden = false;
+      checkbox.focus();
+    });
+
+    checkbox.addEventListener("change", () => {
+      if (checkbox.checked) {
+        clearError();
+      }
+    });
+  </script>
+</body>
+</html>
*** End Patch
