      margin: 0;
      font-size: clamp(1.8rem, 4vw, 2.4rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0.9rem 0 1.5rem;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 1rem;
    }

    .form-field {
      padding: 1rem;
      border: 1px solid rgba(148, 163, 184, 0.35);
      border-radius: 1rem;
      background: rgba(248, 250, 252, 0.85);
    }

    .checkbox-row {
      display: grid;
      grid-template-columns: auto 1fr;
      gap: 0.9rem;
      align-items: start;
    }

    input[type="checkbox"] {
      width: 1.2rem;
      height: 1.2rem;
      margin: 0.15rem 0 0;
      accent-color: var(--accent);
    }

    label {
      font-weight: 600;
      line-height: 1.5;
    }

    .required {
      color: var(--error);
      margin-left: 0.2rem;
