    .status {
      margin: 0.7rem 0 0;
      font-size: 0.95rem;
      line-height: 1.5;
    }

    .helper-text {
      color: var(--muted);
    }

    .error-text {
      color: var(--error);
      font-weight: 600;
    }

    .status {
      min-height: 1.5rem;
      color: #166534;
      font-weight: 600;
    }

    button {
      border: 0;
