    a:focus-visible {
      outline: 3px solid #0f172a;
      outline-offset: 3px;
    }

    input[aria-invalid="true"] {
      outline: 2px solid var(--error);
      outline-offset: 3px;
    }

    [hidden] {
      display: none !important;
    }

    @media (max-width: 480px) {
      .card {
        padding: 1.4rem;
