  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content" tabindex="-1">
    <section class="card" aria-labelledby="page-title">
      <p class="eyebrow">Account setup</p>
      <h1 id="page-title">Confirm your consent</h1>
      <p class="intro">Review the terms once, then confirm your agreement to continue creating your account.</p>

      <form id="consent-form" novalidate>
        <div class="form-field">
          <div class="checkbox-row">
            <input
              id="consent"
              name="consent"
              type="checkbox"
              required
              aria-describedby="consent-help consent-error"
            >
            <label for="consent">
              I agree to the <a href="#terms">Terms of Use</a><span class="required" aria-hidden="true">*</span>
            </label>
          </div>
          <p id="consent-help" class="helper-text">Required to finish setup and activate your access.</p>
          <p id="consent-error" class="error-text" hidden>Error: You must agree to the Terms of Use before continuing.</p>
        </div>

        <button type="submit">Continue</button>
        <p id="form-status" class="status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById("consent-form");
    const checkbox = document.getElementById("consent");
    const error = document.getElementById("consent-error");
    const status = document.getElementById("form-status");

    function clearError() {
      checkbox.removeAttribute("aria-invalid");
      error.hidden = true;
    }

    form.addEventListener("submit", (event) => {
      status.textContent = "";

      if (checkbox.checked) {
        clearError();
        status.textContent = "Consent saved. You're ready to continue.";
        event.preventDefault();
        return;
      }

      event.preventDefault();
      checkbox.setAttribute("aria-invalid", "true");
      error.hidden = false;
      checkbox.focus();
    });

    checkbox.addEventListener("change", () => {
      if (checkbox.checked) {
        clearError();
      }
    });
  </script>
</body>
</html>
